<script setup lang="ts">
import {ref,computed,onMounted,nextTick,watch} from 'vue';import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import BaseCard from '@/components/BaseCard.vue';import AppButton from '@/components/AppButton.vue';import BottomActionBar from '@/components/BottomActionBar.vue';import SectionHeader from '@/components/SectionHeader.vue';import StatusTag from '@/components/StatusTag.vue';import Stage1Status from './Stage1Status.vue';import Stage1Field from './Stage1Field.vue';import Stage1Files from './Stage1Files.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label,methodLabels,cents,amount,Stage1Error} from '../../services/stage1';import type {Data,Page} from '../../services/stage1'
const props=defineProps<{query?:Data}>(),p=useStage1Page('goods_'+(props.query?.id||'new')),{error,busy,loading,pending,dirty}=p,data=ref<Data|null>(null),form=ref<Data>({galleryFileIds:[],detailBlocks:[],methods:[],skus:[]}),categories=ref<Data[]>([]),units=ref<Data[]>([]),dimensions=ref<string[]>([]),expanded=ref(0),adjust=ref<Data|null>(null),history=ref<Data[]>([]),historySku=ref(''),historyPage=ref(1),historyTotal=ref(0)
let replacing=false
const editable=computed(()=>p.has('goods.write')&&data.value?.goods.reviewStatus!=='SUBMITTED'),disabled=computed(()=>!editable.value||busy.value||pending.value),fixedDimensions=computed(()=>data.value?.skus.some((s:Data)=>s.submittedOnce))
watch([form,dimensions],()=>{if(!replacing)dirty.value=true},{deep:true})
function display(v:Data|null){replacing=true;data.value=v;form.value={galleryFileIds:[],detailBlocks:[],methods:[],skus:[],...(v?JSON.parse(JSON.stringify(v.payload)):{})};form.value.skus=(form.value.skus||[]).map((s:Data)=>({...s,enabled:s.enabled!==false,priceInput:s.priceCent==null?'':amount(s.priceCent),weightInput:s.weightGram==null?'':String(s.weightGram/1000)}));dimensions.value=form.value.skus[0]?.specifications.map((s:Data)=>s.name)||[];dirty.value=false;void nextTick(()=>{replacing=false})}
function load(){return p.read(async()=>({goods:props.query?.id||data.value?.goods.id?await stage1Service.read<Data>('/goods/'+(props.query?.id||data.value!.goods.id)):null,categories:await stage1Service.read<Data[]>('/categories'),units:await stage1Service.read<Data[]>('/units')}),v=>{categories.value=v.categories;units.value=v.units;display(v.goods)})}
function addSku(){if(form.value.skus.length>=100)return;form.value.skus.push({enabled:true,code:'',specifications:dimensions.value.map(name=>({name,value:''})),priceInput:'',costInput:'',quantityInput:null,weightInput:''});expanded.value=form.value.skus.length-1}
function dimensionChange(){for(const sku of form.value.skus)sku.specifications=dimensions.value.map((name,index)=>({name,value:sku.specifications?.[index]?.value||''}))}
function grams(value:string){if(!value.trim())return null;if(!/^(0|[1-9][0-9]*)(\.[0-9]{1,3})?$/.test(value))throw new Stage1Error('WEIGHT_INVALID',422);const [whole,fraction='']=value.split('.');return Number(whole)*1000+Number(fraction.padEnd(3,'0'))}
function payload(){const result:Data={};for(const key of ['name','subtitle','categoryId','unitId','brandId','galleryFileIds','detailBlocks','methods','note'])if(form.value[key]!==undefined&&form.value[key]!=='')result[key]=form.value[key];result.skus=form.value.skus.map((s:Data)=>{const sku:Data={...(s.id?{id:s.id}:{}),enabled:s.enabled!==false,specifications:s.specifications||[]};if(s.code)sku.code=s.code;if(s.priceInput!=='')sku.priceCent=cents(String(s.priceInput));if(s.weightInput!=='')sku.weightGram=grams(String(s.weightInput));if(s.imageFileId)sku.imageFileId=s.imageFileId;if(!s.id){if(s.quantityInput!=null)sku.initialQuantity=s.quantityInput;if(p.has('cost.write')&&s.costInput)sku.costCent=cents(String(s.costInput))}return sku});return result}
async function save(){let confirmUnlist=false;if(data.value?.goods.marketStatus==='UPPER'){const yes=await uni.showModal({title:'修改内容将下架重审',content:'保存关键内容后当前商品立即下架，需要重新送审通过。'});if(!yes.confirm)return;confirmUnlist=true}await p.write(()=>p.command<Data>(data.value?'/goods/'+data.value.goods.id+'/content':'/goods',{...(data.value?{expectedVersion:data.value.goods.version,confirmUnlist}:{}),payload:payload()},data.value?'PUT':'POST'),display)}
async function submit(){if(dirty.value||!data.value)await save();if(!data.value||dirty.value||pending.value||error.value)return;const yes=await uni.showModal({title:'提交商品审核？',content:'本次内容与规格将锁定；库存和成本仍通过独立操作维护。'});if(yes.confirm)await p.write(()=>p.command<Data>('/goods/'+data.value!.goods.id+'/submit',{expectedVersion:data.value!.goods.version}),display)}
function openAdjustment(sku:Data,kind:string){if(dirty.value){error.value='请先保存或撤销当前内容修改，再调整库存或成本。';return}adjust.value={id:sku.id,kind,version:kind==='stock'?sku.inventoryVersion:sku.costVersion,before:kind==='stock'?sku.quantity:sku.costCent,target:kind==='stock'?sku.quantity:sku.costCent==null?'':amount(sku.costCent),reason:''}}
async function commitAdjustment(){const value=adjust.value!;await p.write(()=>p.command('/skus/'+value.id+'/'+value.kind,{expectedVersion:value.version,...(value.kind==='stock'?{targetQuantity:value.target}:{costCent:cents(String(value.target))}),reason:value.reason},'PUT'),async()=>{adjust.value=null;await load()})}
async function stockHistory(id:string,page=1){await p.read(()=>stage1Service.read<Page<Data>>('/skus/'+id+'/stock-history',{pageNumber:page,pageSize:20}),v=>{historySku.value=id;historyPage.value=page;historyTotal.value=v.total;history.value=v.records})}
onMounted(load)
</script>
<template><AppPage secondary with-bottom-action :status="loading&&!data&&!form.skus.length?'loading':'ready'"><template #navbar><AppNavbar title="商品内容与规格" centered show-back/></template><view class="s1-product-editor stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="p.recover(load)" @retry="p.retry(load)" @abandon="p.abandon(load)"/><BaseCard v-if="data" class="s1-form"><view class="s1-tags"><StatusTag>{{label(data.goods.reviewStatus)}}</StatusTag><StatusTag>{{label(data.goods.marketStatus)}}</StatusTag><StatusTag v-if="data.goods.forcedOff" tone="error">监管下架</StatusTag></view><text v-if="data.goods.forcedReason">{{data.goods.forcedReason}}</text><text class="s1-copy">内容版本 {{data.goods.contentVersion}}；打开编辑页面不会改变销售状态。</text><view v-for="review in data.reviews" :key="review.contentVersion"><text>内容版本 {{review.contentVersion}} · {{label(review.decision||'SUBMITTED')}}</text><text v-if="review.reason" class="s1-copy">{{review.reason}}</text></view></BaseCard><BaseCard class="s1-form"><SectionHeader title="基本信息"/><Stage1Files v-model="form.galleryFileIds" purpose="GOODS" label="商品图片（第一张为主图）" :maximum="9" :disabled="disabled"/><Stage1Field v-model="form.name" label="商品名称" :maximum="60" required :disabled="disabled"/><Stage1Field v-model="form.subtitle" label="商品卖点" :maximum="120" :disabled="disabled"/><Stage1Field v-model="form.categoryId" label="所属类目" type="select" :options="categories.map(c=>({value:c.id,label:c.name}))" :disabled="disabled" required/><Stage1Field v-model="form.unitId" label="计量单位" type="select" :options="units.map(c=>({value:c.id,label:c.name}))" :disabled="disabled" required/></BaseCard><BaseCard class="s1-form"><SectionHeader title="商品详情"/><view v-for="(block,index) in form.detailBlocks" :key="index" class="s1-block"><Stage1Field v-if="block.type==='text'" v-model="block.text" :label="'文字段落 '+(index+1)" type="textarea" :maximum="10000" :disabled="disabled"/><Stage1Files v-else :model-value="block.fileId?[block.fileId]:[]" purpose="GOODS" :label="'详情图片 '+(index+1)" :maximum="1" :disabled="disabled" @update:model-value="block.fileId=$event[0]||null"/><AppButton variant="quiet" :disabled="disabled" @click="form.detailBlocks.splice(index,1)">移除此段</AppButton></view><AppButton variant="secondary" :disabled="disabled||form.detailBlocks.length>=200" @click="form.detailBlocks.push({type:'text',text:''})">增加文字</AppButton><AppButton variant="secondary" :disabled="disabled||form.detailBlocks.length>=200" @click="form.detailBlocks.push({type:'image',fileId:null})">增加图片</AppButton></BaseCard><BaseCard class="s1-form"><SectionHeader title="销售规格"/><text class="s1-copy">最多 3 个规格维度、100 个 SKU；已引用的 SKU 保持稳定编号。</text><view v-for="(_,index) in dimensions" :key="index"><Stage1Field v-model="dimensions[index]" :label="'维度 '+(index+1)+' 名称'" :maximum="20" :disabled="disabled||fixedDimensions" @update:model-value="dimensionChange"/></view><AppButton v-if="dimensions.length<3&&!fixedDimensions" variant="quiet" :disabled="disabled" @click="dimensions.push('');dimensionChange()">增加规格维度</AppButton><view v-for="(sku,index) in form.skus" :key="sku.id||'new-'+index" class="s1-sku"><view class="s1-sku__heading" @click="expanded=expanded===index?-1:index"><text>SKU {{index+1}} · {{sku.code||'编码未填写'}}</text><text>{{expanded===index?'收起':'展开'}}</text></view><view v-if="expanded===index" class="s1-form"><Stage1Field v-model="sku.enabled" label="启用此 SKU" type="boolean" :disabled="disabled"/><Stage1Field v-model="sku.code" label="SKU 编码" :maximum="64" :disabled="disabled||data?.skus.find((s:any)=>s.id===sku.id)?.submittedOnce" hint="1～64位字母、数字、短横线或下划线"/><Stage1Field v-for="(spec,i) in sku.specifications" :key="i" v-model="spec.value" :label="spec.name||'规格值'" :maximum="30" :disabled="disabled||data?.skus.find((s:any)=>s.id===sku.id)?.submittedOnce"/><Stage1Field v-model="sku.priceInput" label="售价（元）" type="money" :disabled="disabled"/><Stage1Field v-model="sku.weightInput" label="重量（千克）" type="money" :disabled="disabled" hint="最多3位小数；物流必须大于0"/><template v-if="!sku.id"><Stage1Field v-model="sku.quantityInput" label="初始可售库存" type="integer" :disabled="disabled"/><Stage1Field v-if="p.has('cost.write')" v-model="sku.costInput" label="初始成本（元）" type="money" :disabled="disabled" hint="未填写与明确填0含义不同"/></template><template v-else><view v-for="current in data?.skus.filter((s:any)=>s.id===sku.id)||[]" :key="current.id" class="s1-form"><text>当前库存 {{current.quantity}} · 库存版本 {{current.inventoryVersion}}</text><text v-if="p.has('cost.read')">成本 {{amount(current.costCent)}} 元 · 成本版本 {{current.costVersion}}</text><AppButton v-if="p.has('stock.write')" variant="secondary" :disabled="pending||busy||dirty" @click="openAdjustment(current,'stock')">独立调整库存</AppButton><AppButton v-if="p.has('cost.write')" variant="secondary" :disabled="pending||busy||dirty" @click="openAdjustment(current,'cost')">独立调整成本</AppButton><AppButton v-if="p.has('stock.read')" variant="quiet" @click="stockHistory(current.id)">查看库存流水</AppButton></view></template><Stage1Files :model-value="sku.imageFileId?[sku.imageFileId]:[]" purpose="GOODS" label="规格图片" :receipt-key="'sku_'+(sku.id||index)" :maximum="1" :disabled="disabled" @update:model-value="sku.imageFileId=$event[0]||null"/><AppButton v-if="!sku.id" variant="quiet" :disabled="disabled" @click="form.skus.splice(index,1)">移除未保存规格</AppButton><text v-else class="s1-copy">已有 SKU 不物理删除；不再销售时停用。</text></view></view><AppButton v-if="form.skus.length<100" variant="secondary" :disabled="disabled" @click="addSku">增加 SKU</AppButton></BaseCard><BaseCard class="s1-form"><SectionHeader title="履约方式"/><Stage1Field v-model="form.methods" label="适用方式" type="multi" :options="Object.entries(methodLabels).map(([value,label])=>({value,label}))" :disabled="disabled" required/><text class="s1-copy">使用店铺对应类型的全部有效点位；送审前需完成店铺履约配置。</text></BaseCard><BaseCard v-if="adjust" class="s1-form"><SectionHeader :title="adjust.kind==='stock'?'调整目标可售库存':'调整成本'"/><text>当前{{adjust.kind==='stock'?'数量 '+adjust.before:'成本 '+amount(adjust.before)+' 元'}} · 版本 {{adjust.version}}</text><Stage1Field v-model="adjust.target" :label="adjust.kind==='stock'?'目标可售数量':'新成本（元）'" :type="adjust.kind==='stock'?'integer':'money'" required :disabled="busy||pending"/><Stage1Field v-model="adjust.reason" label="调整原因" :maximum="200" required :disabled="busy||pending"/><AppButton :disabled="pending" :loading="busy" @click="commitAdjustment">确认独立调整</AppButton><AppButton variant="quiet" :disabled="busy||pending" @click="adjust=null">取消</AppButton></BaseCard><BaseCard v-if="historySku" class="s1-form"><SectionHeader title="库存流水"/><view v-for="item in history" :key="item.id"><text>{{item.beforeQuantity}} → {{item.afterQuantity}}（变化 {{item.deltaQuantity}}）</text><text class="s1-copy">{{item.reason}} · {{item.at}} · {{item.beforeVersion}} → {{item.afterVersion}}</text></view><AppButton v-if="historyPage*20<historyTotal" variant="quiet" @click="stockHistory(historySku,historyPage+1)">下一页流水</AppButton><AppButton v-if="historyPage>1" variant="quiet" @click="stockHistory(historySku,historyPage-1)">上一页流水</AppButton></BaseCard><AppButton variant="quiet" :loading="loading" @click="load">撤销未保存内容并重新读取</AppButton><BottomActionBar v-if="editable"><AppButton variant="secondary" :disabled="pending" :loading="busy" @click="save">保存草稿</AppButton><AppButton v-if="p.has('goods.submit')" :disabled="pending" :loading="busy" @click="submit">提交审核</AppButton></BottomActionBar></view></AppPage></template>
<style scoped lang="scss">.s1-product-editor{padding:$space-4 $page-gutter}.s1-form{display:flex;flex-direction:column;gap:$space-4;font-size:15px;line-height:1.7;overflow-wrap:anywhere}.s1-tags{display:flex;flex-wrap:wrap;gap:$space-2}.s1-copy{display:block;font-size:13px;color:$color-text-secondary;line-height:1.7}.s1-block,.s1-sku{padding:$space-3;background:$color-group-bg;border-radius:$radius-md}.s1-sku__heading{display:flex;justify-content:space-between;gap:$space-2;min-height:44px;align-items:center;font-size:15px;font-weight:600}.s1-sku>.s1-form{margin-top:$space-3}:deep(.app-button){height:auto;min-height:44px;padding-top:$space-3;padding-bottom:$space-3;line-height:1.5}</style>
